item.aggregated_output:
    70	/// Concurrency is bounded by SLICING each chunk, not by resizing the pool —
    71	/// rayon pools have a fixed thread count, and rebuilding one per step would
    72	/// churn threads for no benefit.
    73	#[derive(Debug)]
    74	pub struct AdaptiveCheckers {
    75	    rung: AtomicUsize,
    76	    /// Best files-per-second seen so far, in millifiles/sec so it can live
    77	    /// in an atomic.
    78	    best_rate_milli: AtomicU64,
    79	    settled: AtomicBool,
    80	}
    81	
    82	impl AdaptiveCheckers {
    83	    pub fn new() -> Self {
    84	        let rung = LADDER
    85	            .iter()
    86	            .position(|value| *value >= ADAPTIVE_FLOOR)
    87	            .unwrap_or(0);
    88	        Self {
    89	            rung: AtomicUsize::new(rung),
    90	            best_rate_milli: AtomicU64::new(0),
    91	            settled: AtomicBool::new(false),
    92	        }
    93	    }
    94	
    95	    /// Concurrency to use for the next chunk.
    96	    pub fn limit(&self) -> usize {
    97	        LADDER[self.rung.load(Ordering::Relaxed).min(LADDER.len() - 1)]
    98	    }
    99	
   100	    /// Fold in one chunk's result and decide the next rung.
   101	    ///
   102	    /// Returns the limit that will be used next, for logging and tests.
   103	    pub fn observe(&self, files: usize, elapsed: std::time::Duration) -> usize {
   104	        if files == 0 || elapsed.is_zero() || self.settled.load(Ordering::Relaxed) {
   105	            return self.limit();
   106	        }
   107	        let rate_milli = ((files as f64 / elapsed.as_secs_f64()) * 1000.0) as u64;
   108	        let best = self.best_rate_milli.load(Ordering::Relaxed);
   109	        let rung = self.rung.load(Ordering::Relaxed);
   110	
   111	        if best == 0 {
   112	            // First measurement: nothing to compare against, so take a step
   113	            // and see. This is the "begin immediately" half of the rule.
   114	            self.best_rate_milli.store(rate_milli, Ordering::Relaxed);
   115	            if rung + 1 < LADDER.len() {
   116	                self.rung.store(rung + 1, Ordering::Relaxed);
   117	            }
   118	            return self.limit();
   119	        }
   120	
   121	        // 5% either way is noise on a filesystem benchmark; require a real
   122	        // improvement before spending more concurrency on the destination.
   123	        if rate_milli > best.saturating_mul(105) / 100 {
   124	            self.best_rate_milli.store(rate_milli, Ordering::Relaxed);
   125	            if rung + 1 < LADDER.len() {
   126	                self.rung.store(rung + 1, Ordering::Relaxed);
   127	            } else {
   128	                self.settled.store(true, Ordering::Relaxed);
   129	            }
   130	        } else if rate_milli < best.saturating_mul(95) / 100 {
   131	            // The last step made things worse — give it back and stop. More
   132	            // concurrency past this point costs the destination without
   133	            // buying throughput, which is the failure mode measured at 32
   134	            // shared threads (24× per-call latency for 1.34× throughput).
   135	            if rung > 0 {
   136	                self.rung.store(rung - 1, Ordering::Relaxed);
   137	            }
   138	            self.settled.store(true, Ordering::Relaxed);
   139	        } else {
   140	            // Flat: this rung is the plateau.
   141	            self.settled.store(true, Ordering::Relaxed);
   142	        }
   143	        self.limit()
   144	    }
   145	
   146	    pub fn is_settled(&self) -> bool {
   147	        self.settled.load(Ordering::Relaxed)
   148	    }
   149	}
   150	
   151	impl Default for AdaptiveCheckers {
   152	    fn default() -> Self {
   153	        Self::new()
   154	    }
   155	}
