   157	/// How a session decides its comparison concurrency.
   158	#[derive(Debug)]
   159	pub enum CheckerPolicy {
   160	    /// Pinned to an exact count by the hidden diagnostic flag. Not a normal
   380	/// The one mutable tuning object for a transfer.
   381	#[derive(Debug)]
   382	pub struct TransferDial {
   383	    chunk_bytes: AtomicUsize,
   384	    prefetch_count: AtomicUsize,
   385	    /// 0 = unset (kernel default), matching the old `Option<usize>`.
   386	    tcp_buffer_bytes: AtomicUsize,
   387	    initial_streams: AtomicUsize,
   388	    // ── ue-r2-2 resize state (all epochs are the wire's monotonic
   389	    // resize ids; 0 is reserved for the initial stream set) ──────────
   390	    /// Settled live stream count. Epoch-0 write is
   391	    /// `set_negotiated_streams`; later writes come from
   392	    /// `resize_settled` on an accepted epoch.
   393	    live_streams: AtomicUsize,
   394	    /// Highest settled logical membership reached in this transfer.
   395	    /// This is deliberately separate from the final count and from the
   396	    /// cumulative number of sockets ever opened.
   397	    peak_streams: AtomicUsize,
   398	    /// Last settled epoch, in-flight proposal, and terminal-refusal bit.
   399	    /// These fields form one arbitration state: observing/claiming them
   400	    /// separately permits an ABA race across a concurrent settlement.
   401	    resize_epochs: Mutex<ResizeEpochState>,
   402	    #[cfg(test)]
   403	    resize_tick_test_hook: Mutex<Option<Arc<ResizeTickTestHook>>>,
   404	    #[cfg(test)]
   405	    resize_settle_test_hook: Mutex<Option<Arc<ResizeSettleTestHook>>>,
   406	    #[cfg(test)]
   407	    resize_lock_sequence: AtomicUsize,
   408	    /// Resize-eligible ticks since the last settle (cooldown clock).
   409	    ticks_since_settle: AtomicU32,
   410	    /// Consecutive same-direction tick counter: positive = "pipe clean
   411	    /// AND cheap dials maxed" streak, negative = "blocked AND cheap
   412	    /// dials floored" streak. Any other tick resets it.
   413	    resize_sustain: AtomicI32,
   414	    /// Wakes deterministic drivers after a valid resize settlement.
   415	    resize_settlement_notify: tokio::sync::Notify,
   416	    // Profile-clamped bounds, fixed at construction.
   417	    ceiling_chunk_bytes: usize,
   418	    ceiling_prefetch: usize,
   419	    ceiling_max_streams: usize,
   420	    ceiling_tcp_buffer_bytes: usize,
   421	    observer: Option<DialObserver>,
   422	}
   423	
   424	impl TransferDial {
   425	    fn lock_resize_epochs(&self) -> ResizeEpochGuard<'_> {
   426	        ResizeEpochGuard {
   427	            inner: self
   428	                .resize_epochs
   429	                .lock()
   430	                .expect("resize epoch state poisoned"),
   431	            #[cfg(test)]
   432	            acquisition: self
   433	                .resize_lock_sequence
   434	                .fetch_add(1, Ordering::SeqCst)
   435	                .saturating_add(1),
   436	        }
   437	    }
   438	
   439	    /// Conservative start with default byte ceilings and stream safety limit.
   440	    pub fn conservative() -> Self {
   441	        Self::conservative_within(None)
   442	    }
   443	
   444	    /// Conservative start bounded by the receiver's advertised
   445	    /// capacity profile. Per the `ue-r2-1b` contract, `0`/absent
   446	    /// fields mean UNKNOWN and keep the (already conservative)
   447	    /// default safety bound — never "unlimited". A profile can only lower
   448	    /// bounds, never raise them above the defaults this slice.
   449	    pub fn conservative_within(profile: Option<&CapacityProfile>) -> Self {
   450	        let mut ceiling_chunk = DIAL_CEILING_CHUNK_BYTES;
   451	        let mut ceiling_prefetch = DIAL_CEILING_PREFETCH;
   452	        let ceiling_streams = receiver_stream_ceiling(profile);
   453	        let initial_streams = receiver_initial_streams(profile);
   454	        let ceiling_tcp = DIAL_CEILING_TCP_BUFFER_BYTES;
   455	        if let Some(profile) = profile {
   456	            if profile.max_chunk_bytes > 0 {
   457	                ceiling_chunk = ceiling_chunk.min(profile.max_chunk_bytes as usize);
   458	            }
   459	            if profile.max_inflight_bytes > 0 {
   460	                // The in-flight budget bounds the CHUNK ceiling first
   461	                // (review ue-r2-1e F1: with max_chunk unknown, a budget
   462	                // smaller than one chunk must still be honored — floor
   463	                // 64 KiB, matching the session's minimum buffer), then
   464	                // prefetch so prefetch × chunk stays within budget
   465	                // (floor of 1 so work still moves).
   466	                let inflight = profile.max_inflight_bytes as usize;
   467	                ceiling_chunk =
   468	                    ceiling_chunk.min(inflight.max(crate::buffer::DATA_PLANE_BUFFER_FLOOR));
   469	                let by_inflight = (inflight / ceiling_chunk.max(1)).max(1);
   470	                ceiling_prefetch = ceiling_prefetch.min(by_inflight);
   471	            }
   472	        }
   473	        Self {
   474	            chunk_bytes: AtomicUsize::new(DIAL_FLOOR_CHUNK_BYTES.min(ceiling_chunk)),
   475	            prefetch_count: AtomicUsize::new(DIAL_FLOOR_PREFETCH.min(ceiling_prefetch)),
   476	            tcp_buffer_bytes: AtomicUsize::new(0),
   477	            initial_streams: AtomicUsize::new(initial_streams),
   478	            live_streams: AtomicUsize::new(initial_streams),
   479	            peak_streams: AtomicUsize::new(initial_streams),
   480	            resize_epochs: Mutex::new(ResizeEpochState::default()),
   481	            #[cfg(test)]
   482	            resize_tick_test_hook: Mutex::new(None),
   483	            #[cfg(test)]
   484	            resize_settle_test_hook: Mutex::new(None),
   485	            #[cfg(test)]
   486	            resize_lock_sequence: AtomicUsize::new(0),
   487	            ticks_since_settle: AtomicU32::new(0),
   488	            resize_sustain: AtomicI32::new(0),
   489	            resize_settlement_notify: tokio::sync::Notify::new(),
   490	            ceiling_chunk_bytes: ceiling_chunk,
   491	            ceiling_prefetch,
   492	            ceiling_max_streams: ceiling_streams,
   493	            ceiling_tcp_buffer_bytes: ceiling_tcp,
   494	            observer: None,
   495	        }
   496	    }
   497	
   498	    /// Attach the optional aggregate observer before sharing this dial.
   499	    /// A disabled trace leaves this `None`, so the hot path performs no
   500	    /// event allocation or role-dependent work.
   501	    pub(crate) fn with_observer(mut self, observer: Option<DialObserver>) -> Self {
   502	        self.observer = observer;
   503	        self
   504	    }
   505	
   506	    pub fn shared(self) -> Arc<Self> {
   507	        Arc::new(self)
   508	    }
   509	
   510	    // ── live reads ───────────────────────────────────────────────────
   511	    pub fn chunk_bytes(&self) -> usize {
   512	        self.chunk_bytes.load(Ordering::Relaxed)
   513	    }
   514	    pub fn prefetch_count(&self) -> usize {
   515	        self.prefetch_count.load(Ordering::Relaxed)
   516	    }
   517	    /// `None` = leave the kernel default (old `tcp_buffer_size`
   518	    /// semantics). Connect-time dial.
   519	    pub fn tcp_buffer_bytes(&self) -> Option<usize> {
   520	        match self.tcp_buffer_bytes.load(Ordering::Relaxed) {
   521	            0 => None,
   522	            n => Some(n),
   523	        }
   524	    }
   525	    pub fn initial_streams(&self) -> usize {
   526	        self.initial_streams.load(Ordering::Relaxed)
   527	    }
   528	    pub fn ceiling_max_streams(&self) -> usize {
   529	        self.ceiling_max_streams
   530	    }
   531	
   532	    /// Record the stream count the negotiation actually settled on
   533	    /// (clamped to the dial's ceiling). This is the epoch-0 settle:
   534	    /// it also seeds `live_streams`, the baseline every `ue-r2-2`
   535	    /// resize proposal steps from.
   536	    pub fn set_negotiated_streams(&self, streams: usize) -> usize {
   537	        let clamped = streams.clamp(1, self.ceiling_max_streams.max(1));
   538	        self.initial_streams.store(clamped, Ordering::Relaxed);
   539	        self.live_streams.store(clamped, Ordering::Relaxed);
   540	        self.peak_streams.store(clamped, Ordering::Relaxed);
   541	        clamped
   542	    }
   543	
   544	    // ── ue-r2-2 resize policy ────────────────────────────────────────
   545	
   546	    /// The settled live stream count (epoch-0 negotiation, then each
   547	    /// accepted resize).
   548	    pub fn live_streams(&self) -> usize {
   549	        self.live_streams.load(Ordering::Relaxed)
   550	    }
   551	
   552	    /// Highest settled logical membership reached by this transfer.
   553	    pub fn peak_streams(&self) -> usize {
   554	        self.peak_streams.load(Ordering::Relaxed)
   555	    }
   556	
   557	    /// Last settled resize epoch (0 = only the initial stream set).
   558	    pub fn resize_epoch(&self) -> u32 {
   559	        self.resize_epochs
   560	            .lock()
   561	            .expect("resize epoch state poisoned")
   562	            .settled_epoch
   563	    }
   564	
   565	    /// True while a proposal is awaiting `resize_settled`.
   566	    pub fn resize_pending(&self) -> bool {
   567	        self.resize_epochs
   568	            .lock()
   569	            .expect("resize epoch state poisoned")
   570	            .pending
   571	            .is_some()
   572	    }
   573	
   574	    pub(crate) fn resize_refused(&self) -> bool {
   575	        self.resize_epochs
   576	            .lock()
   577	            .expect("resize epoch state poisoned")
   578	            .refused
   579	    }
   580	
   581	    fn cheap_dials_maxed(&self) -> bool {
   582	        self.chunk_bytes.load(Ordering::Relaxed) >= self.ceiling_chunk_bytes
   583	            && self.prefetch_count.load(Ordering::Relaxed) >= self.ceiling_prefetch
   584	    }
   585	
   586	    fn cheap_dials_floored(&self) -> bool {
   587	        self.chunk_bytes.load(Ordering::Relaxed)
   588	            <= DIAL_FLOOR_CHUNK_BYTES.min(self.ceiling_chunk_bytes)
   589	            && self.prefetch_count.load(Ordering::Relaxed)
   590	                <= DIAL_FLOOR_PREFETCH.min(self.ceiling_prefetch).max(1)
   591	    }
   592	
   593	    /// One resize-eligible tuner tick. Streams move only as the LAST
   594	    /// escalation step in either direction: the cheap dials must
   595	    /// already be pinned at their ceiling (ADD) or floor (REMOVE), the
   596	    /// signal must hold for [`RESIZE_SUSTAIN_TICKS`] consecutive
   597	    /// ticks, at least [`RESIZE_COOLDOWN_TICKS`] must have passed
   598	    /// since the last settle, and no proposal may be in flight. Idle
   599	    /// ticks (`delta_bytes == 0`) are no signal, matching the cheap
   600	    /// tuner. Bounds: `1..=ceiling_max_streams` (the receiver profile
   601	    /// folded in at construction — `CapacityProfile.max_streams` is
   602	    /// authoritative per the proto). One stream per epoch.
   603	    ///
   604	    /// The caller must forward the returned proposal to the peer and
   605	    /// call [`Self::resize_settled`] with the outcome; until then
   606	    /// every subsequent tick returns `None`.
   607	    pub fn resize_tick(&self, delta_bytes: u64, blocked_ratio: f64) -> Option<ResizeProposal> {
   608	        self.resize_tick_decision(delta_bytes, blocked_ratio)
   609	            .and_then(|(proposal, _)| proposal)
   610	    }
   611	
   612	    fn resize_tick_decision(
   613	        &self,
   614	        delta_bytes: u64,
   615	        blocked_ratio: f64,
   616	    ) -> Option<(Option<ResizeProposal>, DialDecisionReason)> {
   617	        // Keep eligibility, direction, live count, and epoch claim in the
   618	        // same critical section as settlement. Otherwise a resize can
   619	        // settle/reset cooldown between signal calculation and claim, and a
   620	        // stale tuner decision can immediately open the next epoch.
   621	        let mut state = self.lock_resize_epochs();
   622	        if state.refused || state.pending.is_some() {
   623	            return None;
   624	        }
   625	        #[cfg(test)]
   626	        let test_hook = self
   627	            .resize_tick_test_hook
   628	            .lock()
   629	            .expect("resize tick test hook poisoned")
   630	            .clone();
   631	        #[cfg(test)]
   632	        if let Some(hook) = test_hook.as_ref() {
   633	            hook.entered_acquisition
   634	                .store(state.acquisition(), Ordering::SeqCst);
   635	            hook.entered.wait();
   636	            hook.release.wait();
   637	        }
   638	        let ticks = self
   639	            .ticks_since_settle
   640	            .fetch_add(1, Ordering::Relaxed)
   641	            .saturating_add(1);
   642	        if delta_bytes == 0 {
   643	            self.resize_sustain.store(0, Ordering::Relaxed);
   644	            return Some((None, DialDecisionReason::Idle));
   645	        }
   646	        let sustain = if blocked_ratio < DIAL_STEP_UP_BLOCKED_RATIO && self.cheap_dials_maxed() {
   647	            let prev = self.resize_sustain.load(Ordering::Relaxed).max(0);
   648	            let next = prev.saturating_add(1);
   649	            self.resize_sustain.store(next, Ordering::Relaxed);
   650	            next
   651	        } else if blocked_ratio > DIAL_STEP_DOWN_BLOCKED_RATIO && self.cheap_dials_floored() {
   652	            let prev = self.resize_sustain.load(Ordering::Relaxed).min(0);
   653	            let next = prev.saturating_sub(1);
   654	            self.resize_sustain.store(next, Ordering::Relaxed);
   655	            next
   656	        } else {
   657	            self.resize_sustain.store(0, Ordering::Relaxed);
   658	            0
   659	        };
   660	        if sustain == 0 {
   661	            return Some((None, DialDecisionReason::Hysteresis));
   662	        }
   663	        if ticks < RESIZE_COOLDOWN_TICKS {
   664	            return Some((None, DialDecisionReason::Cooldown));
   665	        }
   666	        let add = if sustain >= RESIZE_SUSTAIN_TICKS {
   667	            true
   668	        } else if sustain <= -RESIZE_SUSTAIN_TICKS {
   669	            false
   670	        } else {
   671	            return Some((None, DialDecisionReason::Sustain));
   672	        };
   673	        let live = self.live_streams.load(Ordering::Relaxed).max(1);
   674	        let target = if add {
   675	            (live + 1).min(self.ceiling_max_streams.max(1))
   676	        } else {
   677	            live.saturating_sub(1).max(1)
   678	        };
   679	        if target == live {
   680	            // Already at the bound in the wanted direction.
   681	            self.resize_sustain.store(0, Ordering::Relaxed);
   682	            return Some((None, DialDecisionReason::Bound));
   683	        }
   684	        let Some(epoch) = state.settled_epoch.checked_add(1) else {
   685	            return Some((None, DialDecisionReason::Bound));
   686	        };
   687	        let proposal = ResizeProposal {
   688	            epoch,
   689	            target_streams: target,
   690	            add: target > live,
   691	        };
   692	        state.pending = Some(proposal);
   693	        #[cfg(test)]
   694	        if let Some(hook) = test_hook.as_ref() {
   695	            hook.claimed_acquisition
   696	                .store(state.acquisition(), Ordering::SeqCst);
   697	        }
   698	        self.resize_sustain.store(0, Ordering::Relaxed);
   699	        Some((
   700	            Some(proposal),
   701	            if proposal.add {
   702	                DialDecisionReason::Add
   703	            } else {
   704	                DialDecisionReason::Remove
   705	            },
   706	        ))
   707	    }
   708	
   709	    /// Settle the in-flight proposal with what ACTUALLY happened.
   710	    /// Production passes `accepted = true` only after local membership reaches
   711	    /// the proposal target; a post-ack membership failure faults the session
   712	    /// instead of publishing a partial settlement. `accepted = false` leaves
   713	    /// the live count untouched, consumes the refused epoch, and permanently
   714	    /// disables further proposals on this transfer. Stale epochs (not the
   715	    /// pending one) are ignored. Either way the cooldown clock restarts.
   716	    pub fn resize_settled(&self, epoch: u32, effective_streams: usize, accepted: bool) {
   717	        #[cfg(test)]
   718	        let mut state = {
   719	            let hook = self
   720	                .resize_settle_test_hook
   721	                .lock()
   722	                .expect("resize settle test hook poisoned")
   723	                .clone();
   724	            if let Some(hook) = hook {
   725	                match self.resize_epochs.try_lock() {
   726	                    Ok(state) => {
   727	                        hook.contended.store(false, Ordering::SeqCst);
   728	                        hook.observed.wait();
   729	                        state
   730	                    }
   731	                    Err(std::sync::TryLockError::WouldBlock) => {
   732	                        hook.contended.store(true, Ordering::SeqCst);
   733	                        hook.observed.wait();
   734	                        self.resize_epochs
   735	                            .lock()
   736	                            .expect("resize epoch state poisoned")
   737	                    }
   738	                    Err(std::sync::TryLockError::Poisoned(_)) => {
   739	                        panic!("resize epoch state poisoned")
   740	                    }
   741	                }
   742	            } else {
   743	                self.resize_epochs
   744	                    .lock()
   745	                    .expect("resize epoch state poisoned")
   746	            }
   747	        };
   748	        #[cfg(not(test))]
   749	        let mut state = self
   750	            .resize_epochs
   751	            .lock()
   752	            .expect("resize epoch state poisoned");
   753	        let proposal = state.pending.filter(|pending| pending.epoch == epoch);
   754	        let settled = self.resize_settled_locked(&mut state, epoch, effective_streams, accepted);
   755	        let observation = if settled {
   756	            let live_streams = self.live_streams();
   757	            if accepted {
   758	                self.peak_streams.fetch_max(live_streams, Ordering::Relaxed);
   759	            }
   760	            proposal.map(|proposal| {
   761	                let reason = if !accepted {
   762	                    DialLifecycleReason::Refused
   763	                } else if proposal.add {
   764	                    DialLifecycleReason::Add
   765	                } else {
   766	                    DialLifecycleReason::Remove
   767	                };
   768	                (
   769	                    proposal,
   770	                    reason,
   771	                    live_streams,
   772	                    self.peak_streams(),
   773	                    self.ceiling_max_streams,
   774	                )
   775	            })
   776	        } else {
   777	            None
   778	        };
   779	        drop(state);
   780	        if let (Some(observer), Some((proposal, reason, live_streams, peak_streams, ceiling))) =
   781	            (&self.observer, observation)
   782	        {
   783	            observer.emit(DialObservationEvent::Settlement {
   784	                proposal,
   785	                reason,
   786	                accepted,
   787	                live_streams,
   788	                peak_streams,
   789	                receiver_ceiling: ceiling,
   790	            });
   791	        }
   792	        if settled {
   793	            // Release the tuner only after the optional observer records this
   794	            // epoch. Otherwise its next sample can publish epoch N+1 before
   795	            // epoch N's settlement reaches the trace.
   796	            self.resize_settlement_notify.notify_waiters();
   797	        }
   798	    }
   799	
   800	    fn resize_settled_locked(
   801	        &self,
   802	        state: &mut ResizeEpochState,
   803	        epoch: u32,
   804	        effective_streams: usize,
   805	        accepted: bool,
   806	    ) -> bool {
   807	        if state.pending.map(|pending| pending.epoch) != Some(epoch) || epoch == 0 {
   808	            return false;
   809	        }
   810	        self.ticks_since_settle.store(0, Ordering::Relaxed);
   811	        self.resize_sustain.store(0, Ordering::Relaxed);
   812	        if accepted {
   813	            let clamped = effective_streams.clamp(1, self.ceiling_max_streams.max(1));
