306	fn read_records_from_path(path: &Path, limit: usize) -> Result<Vec<PerformanceRecord>> {
307	    if !path.exists() {
308	        return Ok(Vec::new());
309	    }
310	
311	    let file = File::open(path)?;
312	    let reader = BufReader::new(file);
313	    let mut records = Vec::new();
314	
315	    for line in reader.lines() {
316	        let Ok(line) = line else { continue };
317	        if line.trim().is_empty() {
318	            continue;
319	        }
320	        if let Ok(record) = serde_json::from_str::<PerformanceRecord>(&line) {
321	            records.push(migrate_record(record));
322	        }
323	    }
324	
325	    if limit == 0 || records.len() <= limit {
326	        return Ok(records);
327	    }
328	
329	    let start = records.len().saturating_sub(limit);
330	    Ok(records[start..].to_vec())
331	}
