334	///
335	/// This is safe to call at any time. Records that fail to parse are dropped.
336	/// Returns the number of records migrated, or `Ok(0)` if the file doesn't exist.
337	pub fn migrate_history_file() -> Result<usize> {
338	    let path = history_path()?;
339	    if !path.exists() {
340	        return Ok(0);
341	    }
342	
343	    let records = read_records_from_path(&path, 0)?;
344	    let count = records.len();
345	
346	    let mut file = File::create(&path)
347	        .with_context(|| format!("rewriting history file {}", path.display()))?;
348	    for record in &records {
