443	/// Best-effort rotation that prefers keeping the newest records over enforcing the cap exactly.
444	/// If a concurrent writer appends while we're trimming, we skip rotation to avoid data loss.
445	fn enforce_size_cap(path: &Path, max_bytes: u64) -> Result<()> {
446	    let metadata = match fs::metadata(path) {
447	        Ok(meta) => meta,
448	        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(()),
449	        Err(err) => return Err(err.into()),
450	    };
451	
452	    if metadata.len() <= max_bytes {
453	        return Ok(());
454	    }
455	
456	    // Capture the size we observed so we can detect concurrent appends.
457	    let observed_len = metadata.len();
458	
459	    let file = File::open(path)?;
460	    let reader = BufReader::new(file);
461	    let mut lines: VecDeque<String> = reader
462	        .lines()
463	        .collect::<std::result::Result<Vec<String>, _>>()
464	        .context("read performance history for rotation")?
465	        .into_iter()
466	        .filter(|line| !line.trim().is_empty())
467	        .collect();
468	
469	    if lines.is_empty() {
470	        return Ok(());
471	    }
472	
473	    let mut total_size: usize = lines.iter().map(|l| l.len() + 1).sum();
474	    while total_size as u64 > max_bytes {
475	        if lines.pop_front().is_none() {
476	            break;
477	        }
478	        total_size = lines.iter().map(|l| l.len() + 1).sum();
479	    }
480	
481	    // Re-read metadata to ensure nothing appended during trimming.
482	    if fs::metadata(path).map(|m| m.len()).unwrap_or(observed_len) != observed_len {
483	        return Ok(());
484	    }
485	
486	    let mut file = File::create(path)?;
487	    for line in lines {
488	        writeln!(file, "{line}")?;
489	    }
490	    Ok(())
491	}
