192	pub struct CheckerPool {
193	    pool: Arc<rayon::ThreadPool>,
194	    threads: usize,
195	    policy: Arc<CheckerPolicy>,
196	    /// Times [`CheckerPool::install`] has run.
197	    ///
198	    /// cr-ls1-9: this exists so a test can prove the PRODUCTION diff actually
199	    /// routes through this pool. Without it, deleting the wiring at the call
200	    /// site leaves the pool's own unit tests green and the feature silently
201	    /// gone — which is exactly what the reviewer demonstrated.
202	    installs: Arc<AtomicU64>,
203	}
204	
205	impl CheckerPool {
206	    /// Build the pool. `requested == 0` discovers the concurrency at
207	    /// runtime; any other value pins it (clamped to `1..=MAX_CHECKERS`).
208	    ///
209	    /// The pool is always built at the CEILING the policy could ask for,
210	    /// because rayon pools cannot be resized. Live concurrency is bounded by
211	    /// slicing work, not by the thread count — idle threads park and cost
212	    /// nothing.
213	    pub fn new(requested: usize) -> Result<Self> {
214	        let policy = CheckerPolicy::from_request(requested);
215	        let threads = match &policy {
216	            CheckerPolicy::Fixed(n) => *n,
217	            CheckerPolicy::Adaptive(_) => *LADDER.last().expect("ladder is non-empty"),
218	        }
219	        .clamp(1, MAX_CHECKERS);
220	        let pool = rayon::ThreadPoolBuilder::new()
221	            .num_threads(threads)
222	            .thread_name(|index| format!("blit-checker-{index}"))
223	            .build()
224	            .context("building the destination-comparison thread pool")?;
225	        Ok(Self {
226	            pool: Arc::new(pool),
227	            threads,
228	            policy: Arc::new(policy),
229	            installs: Arc::new(AtomicU64::new(0)),
230	        })
231	    }
232	
233	    /// How many times work has been dispatched onto this pool. Zero after a
234	    /// whole session means the diff never used it.
235	    pub fn installs(&self) -> u64 {
236	        self.installs.load(Ordering::Relaxed)
237	    }
238	
239	    /// Resolve a requested count to the count that will actually be used.
240	    /// Split out so the clamping is testable without spawning threads.
241	    pub fn resolve(requested: usize) -> usize {
242	        match requested {
243	            0 => ADAPTIVE_FLOOR,
244	            n => n.min(MAX_CHECKERS),
245	        }
246	    }
247	
248	    /// Threads the pool owns. This is the ceiling, not the live concurrency
249	    /// — see [`CheckerPool::limit`].
250	    pub fn threads(&self) -> usize {
251	        self.threads
252	    }
253	
254	    /// In-flight checks permitted for the next chunk.
255	    pub fn limit(&self) -> usize {
256	        self.policy.limit().clamp(1, self.threads)
257	    }
258	
259	    /// Fold one chunk's throughput back into the controller.
260	    pub fn observe(&self, files: usize, elapsed: std::time::Duration) {
261	        self.policy.observe(files, elapsed);
262	    }
263	
264	    pub fn policy(&self) -> &CheckerPolicy {
265	        &self.policy
266	    }
267	
268	    /// Run `op` inside the pool, so any rayon parallelism it starts is
269	    /// confined to these threads instead of the global pool.
270	    pub fn install<T: Send>(&self, op: impl FnOnce() -> T + Send) -> T {
271	        self.installs.fetch_add(1, Ordering::Relaxed);
272	        self.pool.install(op)
273	    }
274	}
