  2	//!
  3	//! The predictor maintains lightweight coefficients per workload profile and
  4	//! persists them alongside the performance history log. A simple online
  5	//! gradient-descent update keeps the model responsive while remaining stable.
  6	
  7	use std::collections::HashMap;
