 17	/// Bumped to v2 in §2.8 of `RELEASE_PLAN_v2_2026-05-04.md` —
 18	/// `PredictorProfile` now carries coefficients for two duration
 19	/// targets (planner + transfer) instead of one.
 20	///
 21	/// Bumped to v3 in R56-F1: previously `observe()` trained
 22	/// unconditionally on every record, so dry-run and null-sink
 23	/// records (which the orchestrator passed through anyway) shifted
 24	/// the transfer coefficient toward "writes are free." Filtering
 25	/// new training to `RunKind::Real` doesn't undo coefficients
 26	/// that were already nudged toward bad values; bumping the state
 27	/// version forces `load()` to reset and rebuild from clean
 28	/// real-transfer history.
 29	///
 30	/// `PerformancePredictor::load` resets state on version mismatch
 31	/// so the bump is transparent to existing users; they lose their
 32	/// prior history (which was contaminated anyway).
 33	const STATE_VERSION: u32 = 3;
 34	const STATE_FILENAME: &str = "perf_predictor.json";
 35	
 36	// Default coefficients (ms contributions).
 37	const DEFAULT_ALPHA_MS_PER_FILE: f64 = 0.05;
 38	const DEFAULT_BETA_MS_PER_MB: f64 = 0.01;
 39	const DEFAULT_GAMMA_MS: f64 = 50.0;
 40	
 41	const LEARNING_RATE: f64 = 0.0005;
 42	const MIN_COEFFICIENT: f64 = 0.000001;
 43	
 44	/// Minimum number of observations on a profile before its predictions
 45	/// are considered confident enough to drive decisions. Below this,
 46	/// callers walk the fallback chain (drop fast_path → drop dest_fs →
 47	/// drop src_fs → mode-only). The bound is conservative; with the
 48	/// online gradient-descent updater two or three observations per
 49	/// profile is enough to stabilize the gamma term, and 5 is enough
 50	/// for non-trivial alpha/beta coefficients to settle for typical
 51	/// workloads.
 52	const MIN_OBSERVATIONS_FOR_CONFIDENCE: u64 = 5;
 53	
 54	#[derive(Debug, Clone, Serialize, Deserialize)]
 55	pub struct PredictorCoefficients {
 56	    pub alpha_ms_per_file: f64,
 57	    pub beta_ms_per_mb: f64,
 58	    pub gamma_ms: f64,
 59	}
 60	
 61	impl PredictorCoefficients {
 62	    fn default() -> Self {
 63	        Self {
 64	            alpha_ms_per_file: DEFAULT_ALPHA_MS_PER_FILE,
 65	            beta_ms_per_mb: DEFAULT_BETA_MS_PER_MB,
 66	            gamma_ms: DEFAULT_GAMMA_MS,
 67	        }
 68	    }
 69	
 70	    fn clamp(&mut self) {
 71	        self.alpha_ms_per_file = self.alpha_ms_per_file.max(MIN_COEFFICIENT);
 72	        self.beta_ms_per_mb = self.beta_ms_per_mb.max(MIN_COEFFICIENT);
 73	        self.gamma_ms = self.gamma_ms.max(MIN_COEFFICIENT);
 74	    }
 75	
 76	    fn predict_ms(&self, file_count: usize, total_bytes: u64) -> f64 {
 77	        let files = file_count as f64;
 78	        let mb = bytes_to_mb(total_bytes);
 79	        self.alpha_ms_per_file * files + self.beta_ms_per_mb * mb + self.gamma_ms
 80	    }
 81	
 82	    fn apply_observation(&mut self, file_count: usize, total_bytes: u64, observed_ms: f64) {
 83	        let files = file_count as f64;
 84	        let mb = bytes_to_mb(total_bytes);
 85	        let predicted = self.predict_ms(file_count, total_bytes);
 86	        let error = observed_ms - predicted;
 87	
 88	        self.alpha_ms_per_file += LEARNING_RATE * error * files;
 89	        self.beta_ms_per_mb += LEARNING_RATE * error * mb;
 90	        self.gamma_ms += LEARNING_RATE * error;
 91	        self.clamp();
 92	    }
 93	}
