224	    /// Predict a duration for a workload, walking the profile-key
225	    /// fallback chain until a profile with enough observations to be
226	    /// trusted is found. Returns `None` only if every fallback step
227	    /// has been exhausted without finding a usable profile (i.e.
228	    /// even the mode-only profile has zero observations).
229	    ///
230	    /// Fallback chain (in order):
231	    ///   0: exact `(src_fs, dest_fs, fast_path, skip_unchanged, checksum)`
232	    ///   1: drop `fast_path`
233	    ///   2: also drop `dest_fs`
234	    ///   3: also drop `src_fs` — mode-only profile
235	    ///
236	    /// `MIN_OBSERVATIONS_FOR_CONFIDENCE` gates each step; a profile
237	    /// with fewer observations is skipped to the next fallback.
238	    pub fn predict(
239	        &self,
240	        kind: DurationKind,
241	        mode: TransferMode,
242	        source_fs: Option<&str>,
243	        dest_fs: Option<&str>,
244	        fast_path: Option<&str>,
245	        skip_unchanged: bool,
246	        checksum: bool,
247	        file_count: usize,
248	        total_bytes: u64,
249	    ) -> Option<Prediction> {
250	        // Each tuple is (depth, key). Walk in order; the first match
251	        // with enough observations wins.
252	        let candidates: [(usize, ProfileKey); 4] = [
253	            (
254	                0,
255	                ProfileKey::from_components(
256	                    source_fs.map(str::to_string),
257	                    dest_fs.map(str::to_string),
258	                    mode.clone(),
259	                    fast_path,
260	                    skip_unchanged,
261	                    checksum,
262	                ),
263	            ),
264	            (
265	                1,
266	                ProfileKey::from_components(
267	                    source_fs.map(str::to_string),
268	                    dest_fs.map(str::to_string),
269	                    mode.clone(),
270	                    None,
271	                    skip_unchanged,
272	                    checksum,
273	                ),
274	            ),
275	            (
276	                2,
277	                ProfileKey::from_components(
278	                    source_fs.map(str::to_string),
279	                    None,
280	                    mode.clone(),
281	                    None,
282	                    skip_unchanged,
283	                    checksum,
284	                ),
285	            ),
286	            (
287	                3,
288	                ProfileKey::from_components(None, None, mode, None, skip_unchanged, checksum),
289	            ),
290	        ];
291	
292	        for (depth, key) in candidates.iter() {
293	            if let Some(profile) = self.state.profiles.get(key) {
294	                if profile.observations >= MIN_OBSERVATIONS_FOR_CONFIDENCE {
295	                    let coeffs = match kind {
296	                        DurationKind::Planner => &profile.coefficients.planner,
297	                        DurationKind::Transfer => &profile.coefficients.transfer,
298	                        DurationKind::Total => {
299	                            // Sum-of-predictions for the same input;
300	                            // construct without allocating.
301	                            let p = profile
302	                                .coefficients
303	                                .planner
304	                                .predict_ms(file_count, total_bytes);
305	                            let t = profile
306	                                .coefficients
307	                                .transfer
308	                                .predict_ms(file_count, total_bytes);
309	                            return Some(Prediction {
310	                                predicted_ms: p + t,
311	                                observations: profile.observations,
312	                                fallback_depth: *depth,
313	                            });
314	                        }
315	                    };
316	                    return Some(Prediction {
317	                        predicted_ms: coeffs.predict_ms(file_count, total_bytes),
318	                        observations: profile.observations,
319	                        fallback_depth: *depth,
320	                    });
321	                }
322	            }
323	        }
324	        None
325	    }
