 58	/// Build a `ProfileReport` from the on-disk perf history and
 59	/// predictor state. `limit` matches the CLI's `--limit N` arg —
 60	/// `0` means "all records" per `read_recent_records`'s contract.
 61	pub fn query(limit: usize) -> Result<ProfileReport> {
 62	    let enabled = perf_history::perf_history_enabled()?;
 63	    let records = perf_history::read_recent_records(limit)?;
 64	    let predictor = PerformancePredictor::load().ok();
 65	    let predictor_path = predictor
 66	        .as_ref()
 67	        .map(|pred| pred.path().to_path_buf())
 68	        .filter(|p| p.exists());
 69	
 70	    let predictor = predictor.as_ref().map(|pred| PredictorReport {
 71	        copy: summarize_mode(pred, TransferMode::Copy),
 72	        mirror: summarize_mode(pred, TransferMode::Mirror),
 73	    });
 74	
 75	    Ok(ProfileReport {
 76	        enabled,
 77	        records,
 78	        predictor_path,
 79	        predictor,
 80	    })
 81	}
