 14	pub fn run_diagnostics_perf(ctx: &mut AppContext, args: &PerfArgs) -> Result<()> {
 15	    if args.enable {
 16	        perf::set_enabled(true)?;
 17	        ctx.perf_history_enabled = true;
 18	        println!("Performance history enabled (persisted).");
 19	    }
 20	
 21	    if args.disable {
 22	        perf::set_enabled(false)?;
 23	        ctx.perf_history_enabled = false;
 24	        println!("Performance history disabled (persisted).");
 25	    }
 26	
 27	    if args.clear {
 28	        match perf::clear()? {
 29	            true => println!("Cleared performance history log."),
 30	            false => println!("No performance history log to clear."),
 31	        }
 32	    }
 33	
 34	    // Best-effort refresh of the cached enabled flag — matches
 35	    // pre-A.0 semantics. A malformed `settings.json` here doesn't
 36	    // block the rest of the verb: the startup warning already
 37	    // surfaced the parse error, and we fall back to whatever
 38	    // value AppContext loaded with.
 39	    if let Ok(enabled) = perf::read_enabled() {
 40	        ctx.perf_history_enabled = enabled;
 41	    }
 42	
 43	    let history_path = perf::history_path()?;
 44	    let records = perf::read_records(args.limit)?;
 45	
 46	    if args.json {
 47	        let output = json!({
 48	            "enabled": ctx.perf_history_enabled,
 49	            "history_path": history_path.to_string_lossy(),
 50	            "record_count": records.len(),
 51	            "records": records,
 52	        });
 53	        println!("{}", serde_json::to_string_pretty(&output)?);
 54	        return Ok(());
 55	    }
 56	
 57	    println!(
 58	        "Performance history (showing up to {} entries): {}",
 59	        args.limit,
 60	        records.len()
 61	    );
 62	    println!("History file: {}", history_path.display());
 63	    println!(
 64	        "Status: {}",
 65	        if ctx.perf_history_enabled {
 66	            if records.is_empty() {
 67	                "enabled (no entries yet)"
 68	            } else {
 69	                "enabled"
 70	            }
 71	        } else {
 72	            "disabled via CLI settings"
 73	        }
 74	    );
 75	
 76	    if records.is_empty() {
 77	        return Ok(());
 78	    }
 79	
 80	    let total_runs = records.len();
 81	    let total_runs_f64 = total_runs as f64;
 82	    let avg_planner = records
 83	        .iter()
 84	        .map(|r| r.planner_duration_ms as f64)
 85	        .sum::<f64>()
 86	        / total_runs_f64;
 87	    let avg_transfer = records
 88	        .iter()
 89	        .map(|r| r.transfer_duration_ms as f64)
 90	        .sum::<f64>()
 91	        / total_runs_f64;
 92	    let fast_path_runs = records.iter().filter(|r| r.fast_path.is_some()).count();
 93	    let fast_pct = if total_runs == 0 {
 94	        0.0
 95	    } else {
 96	        100.0 * fast_path_runs as f64 / total_runs_f64
 97	    };
 98	
 99	    println!(
100	        "Fast-path runs: {} ({:.1}%), streaming runs: {}",
101	        fast_path_runs,
102	        fast_pct,
103	        total_runs - fast_path_runs
104	    );
105	    println!(
106	        "Average planner: {:.1} ms | Average transfer: {:.1} ms",
107	        avg_planner, avg_transfer
108	    );
109	
110	    if let Some(last) = records.last() {
111	        let millis = last.timestamp_epoch_ms.min(u64::MAX as u128) as u64;
112	        let timestamp = DateTime::<Utc>::from(UNIX_EPOCH + Duration::from_millis(millis));
113	        let mode = match last.mode {
114	            blit_core::perf_history::TransferMode::Copy => "copy",
115	            blit_core::perf_history::TransferMode::Mirror => "mirror",
116	        };
117	        let fast_path_label = last.fast_path.as_deref().unwrap_or("streaming");
118	
119	        println!("Most recent run:");
120	        println!(
121	            "  Timestamp : {}",
122	            timestamp.format("%Y-%m-%d %H:%M:%S UTC")
123	        );
124	        println!("  Mode      : {}", mode);
125	        println!("  Fast path : {}", fast_path_label);
126	        println!(
127	            "  Planned   : {} file(s), {} bytes",
128	            last.file_count, last.total_bytes
129	        );
130	        println!(
131	            "  Planner   : {} ms | Transfer: {} ms",
132	            last.planner_duration_ms, last.transfer_duration_ms
133	        );
134	        println!(
135	            "  Options   : checksum={} skip_unchanged={} workers={}",
136	            last.options.checksum, last.options.skip_unchanged, last.options.workers
137	        );
138	        if let Some(fs) = &last.source_fs {
139	            println!("  Source FS : {}", fs);
140	        }
141	        if let Some(fs) = &last.dest_fs {
142	            println!("  Dest FS   : {}", fs);
143	        }
144	    }
145	
146	    Ok(())
147	}
